    ensures
        #[trigger] m.len() == 0 <==> m =~= Multiset::empty(),
        #[trigger] m.len() > 0 ==> exists|v: V| 0 < m.count(v),
{
    broadcast use group_multiset_axioms;

    assert(m.len() == 0 <==> m =~= Multiset::empty());
}

